type IconDef =
  | { kind: 'text'; label: string; shape?: 'square'; color: string }
  | { kind: 'devicon'; svg: string; color: string }
  | { kind: 'svg'; render: (color: string) => React.ReactNode; color: string };

function Svg({ children, viewBox = '0 0 24 24' }: { children: React.ReactNode; viewBox?: string }) {
  return (
    <svg className="file-icon-svg" viewBox={viewBox} aria-hidden="true">
      {children}
    </svg>
  );
}

