// A few well-known files are recognized by their exact name rather than an
// extension (Dockerfile has none at all).
const FILENAME_ICONS: Record<string, IconDef> = {
  dockerfile: { kind: 'devicon', svg: DEVICON_DOCKER, color: '#019bc6' },
};

function iconFor(name: string): IconDef | null {
  const lower = name.toLowerCase();
  if (FILENAME_ICONS[lower]) return FILENAME_ICONS[lower];
  if (lower.endsWith('.lock')) return LOCK_ICON;
  const dotIndex = lower.lastIndexOf('.');
  if (dotIndex === -1) return null;
  return EXTENSION_ICONS[lower.slice(dotIndex + 1)] ?? null;
}

/** A small colored mark for well-known file extensions — the real
 * language/format logo (simplified to one flat color) where one exists,
 * or plain colored text as a last resort. Falls back to the generic
 * document glyph for anything not in the list. Used in both the file tree
 * and editor tabs so a file reads the same way in either place. */
export function FileIcon({ name }: { name: string }) {
  const icon = iconFor(name);
  if (!icon) return <span className="file-icon-generic">📄</span>;
  if (icon.kind === 'devicon') {
    return (
      <span className="file-icon-svg-wrap" style={{ color: icon.color }}>
        <svg className="file-icon-svg" viewBox="0 0 128 128" aria-hidden="true" dangerouslySetInnerHTML={{ __html: icon.svg }} />
      </span>
    );
  }
  if (icon.kind === 'svg') {
    return (
      <span className="file-icon-svg-wrap" style={{ color: icon.color }}>
        {icon.render(icon.color)}
      </span>
    );
  }
  const shapeClass = icon.shape === 'square' ? 'file-icon-badge-square' : 'file-icon-badge-plain';
  return (
    <span className={`file-icon-badge ${shapeClass}`} style={{ color: icon.color }}>
      {icon.label}
    </span>
  );
}
